mapper.select:
SELECT	DATE_FORMAT(DATE, '%Y-%m-%d %T' ) AS date, ADMIN_ID AS adminId, SEQ AS seq, PRODUCT AS product, CATEGORY AS category,
OPERATION AS operation, ADMIN_NAME AS adminName, ADMIN_IP AS adminIp, MENU_ID AS menuId, P_MENU_ID AS pMenuId,
INFORMATION AS information, COMMENTS AS comments
FROM	INFO_AUDIT
WHERE	1=1

	AND		( INFORMATION	LIKE CONCAT('%', #{searchStr}, '%') )


	AND		DATE BETWEEN STR_TO_DATE( CONCAT(#{startDt}, '000000'), '%Y%m%d%H%i%s') AND STR_TO_DATE( CONCAT(#{endDt}, '235959'), '%Y%m%d%H%i%s')


	AND		PRODUCT = #{product}


	AND		CATEGORY = #{category}


	AND		OPERATION = #{operation}



		AND	ADMIN_ID IN (
		SELECT ADMIN_ID FROM UI_ADMIN A WHERE 1 = 1 AND ( A.ADMIN_ID = #{adminId2} OR A.ADMIN_TYPE = 'M' )
		)



	AND		ADMIN_ID = #{adminId}


	AND		P_MENU_ID = #{pMenuId}


	AND		MENU_ID NOT IN ('POLICY_DID', 'POLICY_URLIP', 'BLOCK_DID', 'BLOCK_URL', 'BLOCK_IP')


	AND		MENU_ID = #{menuId}

ORDER	BY DATE DESC, SEQ ASC

	LIMIT	${offset}, ${limit}
